// ───── ai-tutor/lib/parser.ts ─────
// lib/parser.ts — incremental parser for the tutor's line protocol.
//
// The model is asked for plain tagged lines (cheap to stream, no half-open JSON):
//
//   REPLY: <Japanese reply, may span lines>
//   TR: <translation>
//   FIX: <what they said> => <corrected> | <why>      (or: FIX: none)
//   TIP: <phrase to try> | <why>                       (or: TIP: none)
//
// `TagStream.push()` returns only the NEW text of the REPLY section so it can be
// forwarded as SSE deltas while the rest of the answer is still being generated.
// Pure TypeScript, no Deno APIs → runs under `node --test` as well.

interface Correction { original: string; corrected: string; explanation: string }
interface Suggestion { text: string; explanation: string }
interface TutorResult {
  reply: string;
  translation: string;
  correction: Correction | null;
  suggestion: Suggestion | null;
}

const TAGS = ['\nTR:', '\nFIX:', '\nTIP:'];
const MAX_FIELD = 700;

function clean(s: string): string {
  return s.replace(/[*`]/g, '').replace(/<\/?think>/gi, '').trim().slice(0, MAX_FIELD);
}

/** Longest suffix of `s` that could still become the start of a tag. */
function heldBack(s: string): number {
  let hold = 0;
  for (const tag of TAGS) {
    const max = Math.min(tag.length - 1, s.length);
    for (let n = max; n > hold; n--) {
      if (tag.startsWith(s.slice(s.length - n))) { hold = n; break; }
    }
  }
  return hold;
}

class TagStream {
  private raw = '';
  private emitted = 0;
  private plain = false;

  /** Feed a chunk; returns text that is safe to show in the reply bubble ('' if none). */
  push(chunk: string): string {
    this.raw += chunk;
    const m = /(^|\n)\s*REPLY:[ \t]*/i.exec(this.raw);

    if (!m) {
      // Model ignored the format: after 24 chars with no tag, stream everything as the reply.
      if (!this.plain && this.raw.length >= 24 && !/^\s*(REPLY|TR|FIX|TIP):/i.test(this.raw)) this.plain = true;
      if (!this.plain) return '';
      const out = this.raw.slice(this.emitted);
      this.emitted = this.raw.length;
      return out.replace(/[*`]/g, '');
    }

    const start = m.index + m[0].length;
    const body = this.raw.slice(start);
    let end = -1;
    for (const tag of TAGS) {
      const i = body.indexOf(tag);
      if (i !== -1 && (end === -1 || i < end)) end = i;
    }
    const safeEnd = end !== -1 ? end : body.length - heldBack(body);
    const visible = body.slice(0, Math.max(0, safeEnd));
    const out = visible.slice(this.emitted);
    this.emitted = Math.max(this.emitted, visible.length);
    return out.replace(/[*`]/g, '');
  }

  /** Call once after the stream ends. */
  finish(): TutorResult {
    const raw = this.raw.replace(/\r/g, '');
    const m = /(^|\n)\s*REPLY:[ \t]*/i.exec(raw);
    if (!m) return { reply: clean(raw), translation: '', correction: null, suggestion: null };

    const body = raw.slice(m.index + m[0].length);
    const section = (tag: string): string => {
      const r = new RegExp('(?:^|\\n)\\s*' + tag + ':[ \\t]*([\\s\\S]*?)(?=\\n\\s*(?:REPLY|TR|FIX|TIP):|$)', 'i').exec('\n' + body);
      return r ? r[1].trim() : '';
    };
    const cut = body.search(/\n\s*(?:TR|FIX|TIP):/i);
    const reply = clean(cut === -1 ? body : body.slice(0, cut));

    return {
      reply,
      translation: clean(section('TR')),
      correction: parseFix(section('FIX')),
      suggestion: parseTip(section('TIP')),
    };
  }
}

function parseFix(line: string): Correction | null {
  line = clean(line);
  if (!line || /^(none|なし|n\/a|-)$/i.test(line) || !line.includes('=>')) return null;
  const [said, rest] = line.split('=>', 2);
  const parts = rest.split('|');
  const corrected = clean(parts[0] ?? '');
  const original = clean(said);
  if (!original || !corrected || original === corrected) return null;
  return { original, corrected, explanation: clean(parts.slice(1).join('|')) };
}

function parseTip(line: string): Suggestion | null {
  line = clean(line);
  if (!line || /^(none|なし|n\/a|-)$/i.test(line)) return null;
  const [text, ...why] = line.split('|');
  const t = clean(text);
  return t ? { text: t, explanation: clean(why.join('|')) } : null;
}

// ───── ai-tutor/lib/providers.ts ─────
// lib/providers.ts — streaming LLM calls with timeouts and primary → fallback failover.
// Uses only fetch/AbortController/TextDecoder, so it also runs under Node 20+.

interface ChatMsg { role: 'system' | 'user' | 'assistant'; content: string }
interface GenOptions { maxTokens: number; temperature: number; signal?: AbortSignal }

class ProviderError extends Error {
  retryable: boolean; status: number; started: boolean;
  constructor(message: string, status: number, retryable: boolean, started: boolean) {
    super(message); this.status = status; this.retryable = retryable; this.started = started;
  }
}

const FIRST_TOKEN_MS = 12_000;   // give up on a provider that has not produced a token
const IDLE_MS = 15_000;          // …or that stalls mid-stream

/** Yields the `data:` payloads of an SSE response. */
async function* sseData(res: Response, onActivity: () => void): AsyncGenerator<string> {
  const reader = res.body!.getReader();
  const dec = new TextDecoder();
  let buf = '';
  try {
    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      onActivity();
      buf += dec.decode(value, { stream: true });
      let i: number;
      while ((i = buf.search(/\r?\n\r?\n/)) !== -1) {
        const block = buf.slice(0, i);
        buf = buf.slice(i + (buf[i] === '\r' ? 4 : 2));
        const data = block.split(/\r?\n/).filter((l) => l.startsWith('data:')).map((l) => l.slice(5).trimStart()).join('\n');
        if (data) yield data;
      }
    }
    const tail = buf.trim();
    if (tail.startsWith('data:')) yield tail.slice(5).trimStart();
  } finally {
    try { await reader.cancel(); } catch { /* ignore */ }
  }
}

async function* guarded(
  url: string, init: RequestInit, extract: (json: any) => string | undefined, opts: GenOptions, label: string,
): AsyncGenerator<string> {
  const ctl = new AbortController();
  const onAbort = () => ctl.abort();
  opts.signal?.addEventListener('abort', onAbort);
  let started = false;
  let timer = setTimeout(() => ctl.abort(), FIRST_TOKEN_MS);
  const bump = () => { clearTimeout(timer); timer = setTimeout(() => ctl.abort(), started ? IDLE_MS : FIRST_TOKEN_MS); };

  try {
    let res: Response;
    try { res = await fetch(url, { ...init, signal: ctl.signal }); }
    catch (e) {
      if (opts.signal?.aborted) throw e;
      throw new ProviderError(`${label} unreachable`, 0, true, false);
    }
    if (!res.ok || !res.body) {
      const retryable = res.status === 429 || res.status >= 500 || res.status === 408;
      try { await res.body?.cancel(); } catch { /* ignore */ }
      throw new ProviderError(`${label} HTTP ${res.status}`, res.status, retryable, false);
    }
    try {
      for await (const data of sseData(res, bump)) {
        if (data === '[DONE]') break;
        let json: any;
        try { json = JSON.parse(data); } catch { continue; }
        const piece = extract(json);
        if (piece) { started = true; bump(); yield piece; }
      }
    } catch (e) {
      if (opts.signal?.aborted) throw e;
      if (e instanceof ProviderError) throw e;
      throw new ProviderError(`${label} stream interrupted`, 0, true, started);
    }
    if (!started) throw new ProviderError(`${label} returned no content`, 502, true, false);
  } finally {
    clearTimeout(timer);
    opts.signal?.removeEventListener('abort', onAbort);
  }
}

function streamGroq(messages: ChatMsg[], model: string, apiKey: string, opts: GenOptions) {
  return guarded(
    'https://api.groq.com/openai/v1/chat/completions',
    {
      method: 'POST',
      headers: { Authorization: `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
      body: JSON.stringify({ model, messages, stream: true, temperature: opts.temperature, max_tokens: opts.maxTokens }),
    },
    (j) => j?.choices?.[0]?.delta?.content || undefined,
    opts, 'groq',
  );
}

function streamGemini(messages: ChatMsg[], model: string, apiKey: string, opts: GenOptions) {
  const system = messages.filter((m) => m.role === 'system').map((m) => m.content).join('\n\n');
  const contents = messages.filter((m) => m.role !== 'system')
    .map((m) => ({ role: m.role === 'assistant' ? 'model' : 'user', parts: [{ text: m.content }] }));
  return guarded(
    `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:streamGenerateContent?alt=sse`,
    {
      method: 'POST',
      // key in a header, not in the URL (URLs end up in logs)
      headers: { 'x-goog-api-key': apiKey, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        systemInstruction: { parts: [{ text: system }] },
        contents,
        generationConfig: { temperature: opts.temperature, maxOutputTokens: opts.maxTokens },
      }),
    },
    (j) => j?.candidates?.[0]?.content?.parts?.map((p: any) => p?.text ?? '').join('') || undefined,
    opts, 'gemini',
  );
}

interface ProviderPlan { name: string; run: (m: ChatMsg[], o: GenOptions) => AsyncGenerator<string> }

/**
 * Try providers in order. Fail over only when NOTHING was streamed yet;
 * if a provider dies mid-answer the error is raised so the client can offer "retry".
 */
async function* generate(plans: ProviderPlan[], messages: ChatMsg[], opts: GenOptions, onProvider?: (name: string) => void): AsyncGenerator<string> {
  let last: unknown = new ProviderError('No AI provider configured', 503, false, false);
  for (const plan of plans) {
    let started = false;
    try {
      onProvider?.(plan.name);
      for await (const piece of plan.run(messages, opts)) { started = true; yield piece; }
      return;
    } catch (e) {
      last = e;
      if (opts.signal?.aborted) throw e;
      if (started) throw e;
      if (e instanceof ProviderError && !e.retryable) continue;   // e.g. 401/400: try the next one anyway
    }
  }
  throw last;
}

// ───── ai-tutor/lib/handler.ts ─────
// lib/handler.ts — the whole tutor API as a pure function of (Request, Deps).
// index.ts wires real Supabase/Deno dependencies; tests wire fakes. No network imports here.





interface Repo {
  createSession(userId: string, level: string, mode: string, lesson: number | null): Promise<string>;
  ownsSession(userId: string, sessionId: string): Promise<boolean>;
  listSessions(userId: string): Promise<unknown[]>;
  recentMessages(sessionId: string, limit: number): Promise<{ role: string; content: string }[]>;
  fullHistory(sessionId: string): Promise<unknown[]>;
  saveTurn(sessionId: string, userText: string, result: TutorResult): Promise<void>;
  countUserMessages(userId: string, sinceIso: string): Promise<number>;
  setLevel(userId: string, level: string): Promise<void>;
  deleteSession(userId: string, sessionId: string): Promise<void>;
}
interface Deps {
  env: (key: string) => string | undefined;
  authenticate: (req: Request) => Promise<{ userId: string; repo: Repo }>;
  plans?: ProviderPlan[];                       // tests inject; production builds from env
  now?: () => number;
}

const enc = new TextEncoder();
const SSE_HEADERS = {
  'Content-Type': 'text/event-stream; charset=utf-8',
  'Cache-Control': 'no-store, no-transform',
  'X-Accel-Buffering': 'no',
};
const COMMON = { 'X-Content-Type-Options': 'nosniff', 'Cache-Control': 'no-store' };

function sse(event: string, data: unknown): Uint8Array {
  return enc.encode(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
}

function buildPlans(env: Deps['env']): ProviderPlan[] {
  const groqKey = env('GROQ_API_KEY'), geminiKey = env('GEMINI_API_KEY');
  const primary = (env('AI_PROVIDER') || 'groq').toLowerCase();
  const legacy = env('AI_MODEL');
  const groqModel = env('AI_MODEL_GROQ') || (primary === 'groq' && legacy) || 'llama-3.3-70b-versatile';
  const geminiModel = env('AI_MODEL_GEMINI') || (primary === 'gemini' && legacy) || 'gemini-2.0-flash';
  const groq: ProviderPlan | null = groqKey ? { name: 'groq', run: (m, o) => streamGroq(m, groqModel as string, groqKey, o) } : null;
  const gem: ProviderPlan | null = geminiKey ? { name: 'gemini', run: (m, o) => streamGemini(m, geminiModel as string, geminiKey, o) } : null;
  return (primary === 'gemini' ? [gem, groq] : [groq, gem]).filter(Boolean) as ProviderPlan[];
}

function errorBody(e: unknown, requestId: string) {
  if (e instanceof HttpError) return { status: e.status, body: { code: e.code, message: e.message, retryable: false } };
  if (e instanceof ProviderError) {
    return {
      status: 503,
      body: {
        code: e.started ? 'stream_interrupted' : 'ai_unavailable',
        message: e.started ? 'The connection to the tutor was interrupted.' : 'The tutor is busy right now. Please try again.',
        retryable: true,
      },
    };
  }
  console.error(`[ai-tutor ${requestId}]`, e);
  return { status: 500, body: { code: 'internal', message: 'Something went wrong.', retryable: true } };
}

async function handle(req: Request, deps: Deps): Promise<Response> {
  const requestId = crypto.randomUUID().slice(0, 8);
  const allowed = allowedOrigins(deps.env('ALLOWED_ORIGINS'));
  const origin = req.headers.get('Origin');
  const cors = corsHeaders(origin, allowed);
  const json = (status: number, body: unknown, extra: Record<string, string> = {}) =>
    new Response(JSON.stringify(body), { status, headers: { ...COMMON, ...cors, ...extra, 'Content-Type': 'application/json' } });

  if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers: cors });
  if (req.method !== 'POST') return json(405, { success: false, code: 'method', error: 'Method not allowed' });
  if (origin && !isAllowed(origin, allowed)) return json(403, { success: false, code: 'origin', error: 'Origin not allowed' });

  try {
    const { userId, repo } = await deps.authenticate(req);
    const len = Number(req.headers.get('content-length') || 0);
    if (len > 16 * 1024) throw new HttpError(413, 'too_large', 'Request too large');
    const body = parseBody(await req.text());

    switch (body.action) {
      case 'create_session': {
        const id = await repo.createSession(userId, body.level, body.mode, body.lesson);
        return json(200, { success: true, data: { sessionId: id } });
      }
      case 'get_sessions':
        return json(200, { success: true, data: await repo.listSessions(userId) });
      case 'get_history':
        if (!(await repo.ownsSession(userId, body.sessionId!))) throw new HttpError(404, 'not_found', 'Conversation not found');
        return json(200, { success: true, data: await repo.fullHistory(body.sessionId!) });
      case 'delete_session':
        if (!(await repo.ownsSession(userId, body.sessionId!))) throw new HttpError(404, 'not_found', 'Conversation not found');
        await repo.deleteSession(userId, body.sessionId!);
        return json(200, { success: true });
      case 'update_profile':
        await repo.setLevel(userId, body.level);
        return json(200, { success: true });
      case 'send_message':
        return await sendMessage(body, userId, repo, deps, { json, cors, requestId });
    }
  } catch (e) {
    const { status, body } = errorBody(e, requestId);
    const extra: Record<string, string> = {};
    if (e instanceof HttpError && e.status === 429) extra['Retry-After'] = '30';
    return json(status, { success: false, error: body.message, ...body, requestId }, extra);
  }
  return json(400, { success: false, code: 'bad_action', error: 'Unknown action' });
}

async function sendMessage(
  body: TutorRequest, userId: string, repo: Repo, deps: Deps,
  io: { json: (s: number, b: unknown, h?: Record<string, string>) => Response; cors: Record<string, string>; requestId: string },
): Promise<Response> {
  const now = (deps.now ?? Date.now)();
  const perMin = Number(deps.env('TUTOR_RATE_PER_MIN') || 10);
  const perHour = Number(deps.env('TUTOR_RATE_PER_HOUR') || 100);
  const [m1, h1] = await Promise.all([
    repo.countUserMessages(userId, new Date(now - 60_000).toISOString()),
    repo.countUserMessages(userId, new Date(now - 3_600_000).toISOString()),
  ]);
  if (m1 >= perMin || h1 >= perHour) throw new HttpError(429, 'rate_limited', 'Too many messages. Please wait a moment.');

  let sessionId = body.sessionId;
  if (sessionId) {
    if (!(await repo.ownsSession(userId, sessionId))) throw new HttpError(404, 'not_found', 'Conversation not found');
  } else {
    sessionId = await repo.createSession(userId, body.level, body.mode, body.lesson);
  }

  const history = await repo.recentMessages(sessionId, 8);
  const messages: ChatMsg[] = [
    { role: 'system', content: buildSystemPrompt(body) },
    ...history.map((m): ChatMsg => m.role === 'user'
      ? { role: 'user', content: wrapLearnerMessage(sanitizeText(m.content, 500)) }
      : { role: 'assistant', content: 'REPLY: ' + sanitizeText(m.content, 600) }),
    { role: 'user', content: wrapLearnerMessage(body.message) },
  ];

  const plans = deps.plans ?? buildPlans(deps.env);
  const spec = LEVEL_SPEC[body.level];
  const ac = new AbortController();
  const overall = setTimeout(() => ac.abort(), 45_000);
  const sid = sessionId;

  async function runTurn(onDelta: (t: string) => void) {
    const ts = new TagStream();
    let provider = '';
    for await (const piece of generate(plans, messages, { maxTokens: spec.maxTokens, temperature: 0.4, signal: ac.signal }, (n) => { provider = n; })) {
      const d = ts.push(piece);
      if (d) onDelta(d);
    }
    const result = ts.finish();
    if (!result.reply) throw new ProviderError('empty reply', 502, true, false);
    let saved = true;
    try { await repo.saveTurn(sid, body.message, result); } catch (e) { saved = false; console.error(`[ai-tutor ${io.requestId}] save failed`, e); }
    return { result, provider, saved };
  }

  const finalPayload = (r: Awaited<ReturnType<typeof runTurn>>) => ({
    sessionId: sid, level: body.level, mode: body.mode, provider: r.provider, saved: r.saved,
    reply: r.result.reply, translation: r.result.translation,
    correction: r.result.correction, suggestion: r.result.suggestion,
  });

  if (!body.stream) {
    try {
      const r = await runTurn(() => {});
      return io.json(200, { success: true, data: finalPayload(r) });
    } finally { clearTimeout(overall); }
  }

  let gone = false;                                    // client closed the connection
  const stream = new ReadableStream<Uint8Array>({
    async start(controller) {
      const send = (ev: string, d: unknown) => { try { controller.enqueue(sse(ev, d)); } catch { /* client gone */ } };
      send('meta', { sessionId: sid, requestId: io.requestId });
      try {
        const r = await runTurn((t) => send('delta', { t }));
        send('done', finalPayload(r));
      } catch (e) {
        if (!gone) {
          if (ac.signal.aborted && !(e instanceof ProviderError)) {
            send('error', { code: 'timeout', message: 'The tutor took too long to answer.', retryable: true });
          } else {
            send('error', errorBody(e, io.requestId).body);
          }
        }
      } finally {
        clearTimeout(overall);
        try { controller.close(); } catch { /* already closed */ }
      }
    },
    cancel() { gone = true; ac.abort(); clearTimeout(overall); },
  });
  return new Response(stream, { status: 200, headers: { ...COMMON, ...SSE_HEADERS, ...io.cors } });
}

// ───── ai-tutor/index.ts ─────
// supabase/functions/ai-tutor/index.ts — thin Deno wrapper around lib/handler.ts.
//
// Deploy:   supabase functions deploy ai-tutor
// Secrets:  supabase secrets set GROQ_API_KEY=... GEMINI_API_KEY=... AI_PROVIDER=groq \
//             ALLOWED_ORIGINS="https://biki76.github.io,http://localhost:8000"
// Keep the default "Verify JWT" ON for this function (do not pass --no-verify-jwt).

async function authenticate(req: Request): Promise<{ userId: string; repo: Repo }> {
  const header = req.headers.get('Authorization') || '';
  const token = header.startsWith('Bearer ') ? header.slice(7).trim() : '';
  if (!token) throw new HttpError(401, 'unauthorized', 'Please sign in to use the tutor.');

  // The user's own JWT is forwarded, so every query below is subject to RLS.
  const db = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_ANON_KEY')!, {
    global: { headers: { Authorization: `Bearer ${token}` } },
    auth: { persistSession: false, autoRefreshToken: false },
  });
  const { data, error } = await db.auth.getUser(token);      // server-side JWT validation
  if (error || !data?.user) throw new HttpError(401, 'unauthorized', 'Please sign in to use the tutor.');
  const userId = data.user.id;

  const repo: Repo = {
    async createSession(uid, level, mode, lesson) {
      const { data: s, error: e } = await db.from('chat_sessions')
        .insert({ user_id: uid, jlpt_level: level, mode, lesson }).select('id').single();
      if (e) throw e;
      return s.id as string;
    },
    async ownsSession(uid, sid) {
      const { data: s, error: e } = await db.from('chat_sessions').select('id').eq('id', sid).eq('user_id', uid).maybeSingle();
      if (e) throw e;
      return !!s;
    },
    async listSessions(uid) {
      const { data: rows, error: e } = await db.from('chat_sessions')
        .select('id, jlpt_level, mode, lesson, created_at, updated_at')
        .eq('user_id', uid).order('updated_at', { ascending: false }).limit(20);
      if (e) throw e;
      return rows ?? [];
    },
    async recentMessages(sid, limit) {
      const { data: rows, error: e } = await db.from('chat_messages')
        .select('role, content').eq('session_id', sid).order('created_at', { ascending: false }).limit(limit);
      if (e) throw e;
      return (rows ?? []).reverse();
    },
    async fullHistory(sid) {
      const { data: rows, error: e } = await db.from('chat_messages')
        .select('id, role, content, correction, suggestion, created_at')
        .eq('session_id', sid).order('created_at', { ascending: true }).limit(500);
      if (e) throw e;
      return rows ?? [];
    },
    async saveTurn(sid, userText, r) {
      // two inserts, not one: rows of a single statement share the same created_at
      const a = await db.from('chat_messages').insert({ session_id: sid, role: 'user', content: userText });
      if (a.error) throw a.error;
      const b = await db.from('chat_messages').insert({
        session_id: sid, role: 'assistant', content: r.reply, correction: r.correction, suggestion: r.suggestion,
      });
      if (b.error) throw b.error;
      await db.from('chat_sessions').update({ updated_at: new Date().toISOString() }).eq('id', sid);
    },
    async countUserMessages(_uid, sinceIso) {
      const { count, error: e } = await db.from('chat_messages')
        .select('id', { count: 'exact', head: true }).eq('role', 'user').gte('created_at', sinceIso);
      if (e) throw e;
      return count ?? 0;
    },
    async setLevel(uid, level) {
      const { error: e } = await db.from('user_profiles').upsert({ id: uid, jlpt_level: level });
      if (e) throw e;
    },
    async deleteSession(uid, sid) {
      const { error: e } = await db.from('chat_sessions').delete().eq('id', sid).eq('user_id', uid);
      if (e) throw e;
    },
  };
  return { userId, repo };
}

Deno.serve((req) => handle(req, { env: (k) => Deno.env.get(k), authenticate }));
